/**
 * kon-blocks
 *
 * Lego-style block system for dynamic page layouts with drag & drop. Includes Hero, Text, Image, Video, Grid, Cards, Quote, CTA, Embed, Divider, and Spacer blocks.
 */
export interface BlocksApi {
  /**
   * Delete a block
   *
   * Removes one block from its page.
   *
   * REST: `DELETE /api/page-builder/blocks/{id}` · scope `kon:blocks:borrar-bloque`
   * idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `blocks__borrar-bloque`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly borrarBloque: Operation<BorrarBloqueParams, BorrarBloqueResponse>;
  /**
   * Delete a page
   *
   * Deletes a page and all its blocks. Cannot be undone.
   *
   * REST: `DELETE /api/page-builder/pages/{id}` · scope `kon:blocks:borrar-pagina`
   * idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `blocks__borrar-pagina`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly borrarPagina: Operation<BorrarPaginaParams, BorrarPaginaResponse>;
  /**
   * Clone a page
   *
   * Copies a page and its blocks as a new draft (never as homepage). Slug and title default to '<slug>-copy' and '<title> (Copy)'.
   *
   * REST: `POST /api/page-builder/pages/{id}/clone` · scope `kon:blocks:clonar-pagina`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `blocks__clonar-pagina`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly clonarPagina: Operation<ClonarPaginaParams, ClonarPaginaResponse>;
  /**
   * Add a block to a page
   *
   * Appends a block (after the last one unless sortOrder is given). The content is sanitized for its type before it is stored.
   *
   * REST: `POST /api/page-builder/pages/{pageId}/blocks` · scope `kon:blocks:crear-bloque`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `blocks__crear-bloque`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearBloque: Operation<CrearBloqueParams, CrearBloqueResponse>;
  /**
   * Create a page
   *
   * Creates a page (draft by default) and, optionally, its blocks. The slug is derived from the title when missing. Making it the homepage needs a staff account.
   *
   * REST: `POST /api/page-builder/pages` · scope `kon:blocks:crear-pagina`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `blocks__crear-pagina`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearPagina: Operation<CrearPaginaParams, CrearPaginaResponse>;
  /**
   * Create a block template
   *
   * Saves a reusable block (name, block type and content).
   *
   * REST: `POST /api/page-builder/templates` · scope `kon:blocks:crear-plantilla`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `blocks__crear-plantilla`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearPlantilla: Operation<CrearPlantillaParams, CrearPlantillaResponse>;
  /**
   * Duplicate a block
   *
   * Copies a block to the end of the same page (name gets a '(Copy)' suffix).
   *
   * REST: `POST /api/page-builder/blocks/{id}/duplicate` · scope `kon:blocks:duplicar-bloque`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `blocks__duplicar-bloque`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly duplicarBloque: Operation<DuplicarBloqueParams, DuplicarBloqueResponse>;
  /**
   * Update a block
   *
   * Changes the given block fields; new content is sanitized for the block type.
   *
   * REST: `PATCH /api/page-builder/blocks/{id}` · scope `kon:blocks:editar-bloque`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `blocks__editar-bloque`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly editarBloque: Operation<EditarBloqueParams, EditarBloqueResponse>;
  /**
   * Update a page
   *
   * Changes the given page fields. Publishing sets publishedAt when it was empty; changing the slug checks it is free; isHomepage needs a staff account.
   *
   * REST: `PATCH /api/page-builder/pages/{id}` · scope `kon:blocks:editar-pagina`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `blocks__editar-pagina`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly editarPagina: Operation<EditarPaginaParams, EditarPaginaResponse>;
  /**
   * List pages
   *
   * Paginated list of page-builder pages, newest update first. The public (and any caller without the content role) only sees published pages that do not require a session; staff and agents with contenido:editar can filter by any status.
   *
   * REST: `GET /api/page-builder/pages` · scope `kon:blocks:listar-paginas`
   * idempotent (safe to retry) · MCP tool `blocks__listar-paginas`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarPaginas: PageableOperation<ListarPaginasParams, ListarPaginasResponse, ListarPaginasItem>;
  /**
   * List block templates
   *
   * Active block templates, most used first, optionally filtered by category or block type.
   *
   * REST: `GET /api/page-builder/templates` · scope `kon:blocks:listar-plantillas`
   * idempotent (safe to retry) · MCP tool `blocks__listar-plantillas`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarPlantillas: Operation<ListarPlantillasParams, ListarPlantillasResponse>;
  /**
   * Get a page with its blocks
   *
   * One page by uuid or slug, with its visible blocks in order (block content sanitized). Drafts and session-only pages are a 404 for whoever cannot see them.
   *
   * REST: `GET /api/page-builder/pages/{id}` · scope `kon:blocks:obtener-pagina`
   * idempotent (safe to retry) · MCP tool `blocks__obtener-pagina`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly obtenerPagina: Operation<ObtenerPaginaParams, ObtenerPaginaResponse>;
  /**
   * Publish one block as its own page
   *
   * Creates (201) or updates (200, same slug) a page that holds exactly one block. Republishing replaces the previous block instead of duplicating it, so it is safe to call again with the same slug.
   *
   * REST: `POST /api/page-builder/pages/from-block` · scope `kon:blocks:publicar-bloque-como-pagina`
   * idempotent (safe to retry) · MCP tool `blocks__publicar-bloque-como-pagina`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly publicarBloqueComoPagina: Operation<PublicarBloqueComoPaginaParams, PublicarBloqueComoPaginaResponse>;
  /**
   * Render a published page
   *
   * A published page ready to paint: page metadata plus visible blocks (scheduled visibility applied) with transform URLs for their media. Session-only pages need a session.
   *
   * REST: `GET /api/page-builder/render/{slug}` · scope `kon:blocks:renderizar-pagina`
   * idempotent (safe to retry) · MCP tool `blocks__renderizar-pagina`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly renderizarPagina: Operation<RenderizarPaginaParams, RenderizarPaginaResponse>;
  /**
   * Reorder the blocks of a page
   *
   * Sets sortOrder for up to 500 blocks of the page in one go. Blocks of other pages are ignored. Sending the same order twice leaves the same state.
   *
   * REST: `POST /api/page-builder/pages/{pageId}/blocks/reorder` · scope `kon:blocks:reordenar-bloques`
   * idempotent (safe to retry) · MCP tool `blocks__reordenar-bloques`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly reordenarBloques: Operation<ReordenarBloquesParams, ReordenarBloquesResponse>;
  /**
   * List block types
   *
   * The block types a page can hold, each with the descriptor of its content fields.
   *
   * REST: `GET /api/page-builder/block-types` · scope `kon:blocks:tipos-de-bloque`
   * idempotent (safe to retry) · MCP tool `blocks__tipos-de-bloque`
   * Errors: `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly tiposDeBloque: Operation<void, TiposDeBloqueResponse>;
  /**
   * Count one use of a template
   *
   * Increments the usage counter of a template (it orders the template list).
   *
   * REST: `POST /api/page-builder/templates/{id}/use` · scope `kon:blocks:usar-plantilla`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `blocks__usar-plantilla`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly usarPlantilla: Operation<UsarPlantillaParams, UsarPlantillaResponse>;
}
